links=[('최신 실행 파일','EngineMigrator-runtime-dependency-preview-20261023/EngineMigrator.App.exe'),('배포 ZIP','EngineMigrator-runtime-dependency-preview-20261023.zip'),('사용 가이드','../docs/guide.html'),('실행 검증 근거','runtime-dependency-tests/milestone-verification.json'),('프로젝트 왕복 대조','runtime-dependency-roundtrip-v1/PROJECT-29fea61cb04f/project-roundtrip-verification.json'),('실제 변환 대응표','runtime-dependency-roundtrip-v1/PROJECT-29fea61cb04f/resource-port.html'),('이전 단계 보고서','development-report-runtime-dormant-20261023.html')]
